"""Public decoy keys for exchangeability (permutation) tests.

Decoy key i for a given seed = SHA256("provenmark/decoy" || uint64_le(seed) || uint64_le(i)). They are derived from
public constants only, independently of any real key, so a real key and its decoys are exchangeable under the null
hypothesis; anyone can regenerate them. Used by the cue / xc / xcue detectors and by the model-audit tools.
(The keyed delivery holdout uses its own domain, "provenmark/holdout-decoy", in holdout.decoy_keys_many.)
"""
from __future__ import annotations

import hashlib


def decoy_keys(n: int, seed: int = 0) -> list[bytes]:
    return [hashlib.sha256(b"provenmark/decoy" + seed.to_bytes(8, "little") + i.to_bytes(8, "little")).digest()
            for i in range(n)]
